/*
 * A213309  Numbers with exactly 2 nonprime substrings (substrings with
 *          leading zeros are considered to be nonprime).
 * https://oeis.org/A213309
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, base
 * Formula:   A213309 – numbers with exactly two nonprime substrings. The
 *            sequence is finite; it is generated by brute‑force search
 * Range:     u8 n <= 48, u16 n <= 130, u32 n <= 130, u64 n <= 130,
 *            u128 n <= 130, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>

/* Wrap the prime sieve limit in a macro so it is a compile‑time constant. */
#define PRIMES_MAX 1000000

/* Prime table used to test the substrings.  It is initialised once on
   first use. */
static bool prime_tbl[PRIMES_MAX];
static bool prime_tbl_inited = false;

static void init_prime_tbl(void)
{
    if (prime_tbl_inited) return;
    for (int i = 0; i < PRIMES_MAX; ++i) prime_tbl[i] = true;
    prime_tbl[0] = prime_tbl[1] = false;
    for (int p = 2; (long long)p * p < PRIMES_MAX; ++p)
        if (prime_tbl[p])
            for (long long q = (long long)p * p; q < PRIMES_MAX; q += p)
                prime_tbl[q] = false;
    prime_tbl_inited = true;
}

/* Count non‑prime substrings of a decimal integer.  Leading zeros are
   considered non‑prime. */
static int count_nonprime_substrings(int value)
{
    int digits[10];
    int d = 0;
    int tmp = value;
    if (tmp == 0) {
        digits[d++] = 0;
    } else {
        while (tmp > 0) {
            digits[d++] = tmp % 10;
            tmp /= 10;
        }
        /* reverse to obtain the correct order */
        for (int i = 0; i < d / 2; ++i) {
            int t = digits[i];
            digits[i] = digits[d - 1 - i];
            digits[d - 1 - i] = t;
        }
    }

    int cnt = 0;
    for (int i = 0; i < d; ++i) {
        if (digits[i] == 0) {
            /* All substrings starting at i have a leading zero – nonprime. */
            cnt += d - i;
            continue;
        }
        int val = 0;
        for (int j = i; j < d; ++j) {
            val = val * 10 + digits[j];
            if (!prime_tbl[val]) ++cnt;
        }
    }
    return cnt;
}

/* Cache of found values – the sequence has only 130 terms, so 200 slots
   are sufficient for any seq_t size. */
static seq_t terms[200];
static size_t terms_len = 0;

/* Current candidate to test; starts at 1 because we search from the
   smallest positive integer. */
static int current_candidate = 1;

/* Main lookup function.  It can be called in any order; the results are
   memoised in the static array above. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* offset is 1 – undefined for 0 */

    init_prime_tbl();

    /* Generate terms until we have at least `n` of them. */
    while (terms_len < (size_t)n) {
        if (current_candidate >= PRIMES_MAX) break;  /* protection */

        if (count_nonprime_substrings(current_candidate) == 2) {
            if (terms_len < sizeof(terms)/sizeof(terms[0]))
                terms[terms_len++] = (seq_t)current_candidate;
        }
        ++current_candidate;
    }

    if (n <= terms_len) return terms[n - 1];
    /* Sequence is finite; all later terms are zero. */
    return (seq_t)0;
}
